INSERT INTO feature VALUES('several-outputs','calculus','Functions of several outputs','call-by-push-value','implemented','notable',NULL,'A function writes its outputs as a group, `-> (s : Integer, d : Integer)`, under a row too, `-> -F [Partial] (s : Integer, d : Integer)`, and its body''s tail returns a value at each, positionally or by label, `(.d = e, .s = e)`; a caller binds each output to its own name, `let (s, d) = f(m, n);` or `let (.s, .d) = …`, selects one, `f(m, n).s`, collects them into the record of the outputs with `~ports e`, `let r = ~ports (f m n);`, or plugs every output into the next function''s inputs in order, `f(m, n) |> g`. A call of several outputs read as one value anywhere else is refused `OutputsAsOneValue`, which names the output group and `~ports e`. The core returns them together through a many-value returner, so several outputs build no product; a label naming no output, or one written twice, is refused at the label.','core-term core-checker core-sequent core-incremental surface-lowering surface-pretty','corpus/ledger/features/several-outputs.gandr corpus/ledger/syntax/binary-expression.pipe.gandr corpus/ledger/diagnostics/OutputsAsOneValue.gandr crates/surface-lowering/src/lower/arity/tests.rs','corpus/ledger/features/several-outputs.gandr',NULL);
